# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BAKARA SURESİ 177. AYETTE İYİLİK (BİRR / الْبِرُّ) KAVRAMININ BOYUTLARI</text>\n  <rect x="20" y="45" width="210" height="110" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. İMAN ESASLARI (AKİDE)</text>\n  <text x="125" y="90" text-anchor="middle" font-size="10.5" fill="#1d4ed8">• Allah\'a (c.c.) iman</text>\n  <text x="125" y="108" text-anchor="middle" font-size="10.5" fill="#1d4ed8">• Ahiret gününe iman</text>\n  <text x="125" y="126" text-anchor="middle" font-size="10.5" fill="#1d4ed8">• Meleklere ve Kitaplara iman</text>\n  <text x="125" y="144" text-anchor="middle" font-size="10.5" fill="#1d4ed8">• Peygamberlere iman</text>\n  <rect x="245" y="45" width="210" height="110" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. İBADET VE İNFAK</text>\n  <text x="350" y="90" text-anchor="middle" font-size="10.5" fill="#166534">• Namazı dosdoğru kılmak</text>\n  <text x="350" y="108" text-anchor="middle" font-size="10.5" fill="#166534">• Zekâtı vermek</text>\n  <text x="350" y="126" text-anchor="middle" font-size="10.5" fill="#166534">• Sevdiği maldan akrabaya, yetime,</text>\n  <text x="350" y="144" text-anchor="middle" font-size="10.5" fill="#166534">yoksula, yolda kalmışa harcamak</text>\n  <rect x="470" y="45" width="210" height="110" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">3. GÜZEL AHLAK (FAZİLET)</text>\n  <text x="575" y="90" text-anchor="middle" font-size="10.5" fill="#78350f">• Verdiği sözü (ahdi) tutmak</text>\n  <text x="575" y="108" text-anchor="middle" font-size="10.5" fill="#78350f">• Darlıkta ve hastalıkta sabretmek</text>\n  <text x="575" y="126" text-anchor="middle" font-size="10.5" fill="#78350f">• Savaş ve zorluk anında metanet</text>\n  <text x="575" y="144" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">→ SÂDIKLAR VE MÜTTAKİLER</text>\n  <rect x="20" y="168" width="660" height="76" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="192" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">TEMEL MESAJ: «لَيْسَ الْبِرَّ أَنْ تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ ...»</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">Gerçek iyilik (birr) şekilcilik değil; iman, salih amel (ibadet-yardımlaşma) ve ahlak bütünlüğüdür!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BAKARA 177. AYETTEKİ TEMEL KAVRAMLAR: BİRR, İNFAK, AHD, SABIR VE TAKVA</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">İNFAK EDİLEN KESİMLER</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#1e3a8a">• ذَوِي الْقُرْبَى : Yakın akrabalar</text>\n  <text x="35" y="120" font-size="11" font-weight="bold" fill="#1e3a8a">• الْيَتَامَى : Yetimler (babasını kaybetmiş çocuklar)</text>\n  <text x="35" y="144" font-size="11" font-weight="bold" fill="#1e3a8a">• الْمَسَاكِين : Yoksullar / geçim sıkıntısı çekenler</text>\n  <text x="35" y="168" font-size="11" font-weight="bold" fill="#1e3a8a">• ابْنَ السَّبِيلِ : Yolda kalmışlar (yolcular)</text>\n  <text x="35" y="192" font-size="11" font-weight="bold" fill="#1e3a8a">• السَّائِلِين : İhtiyacını arz edip yardım isteyenler</text>\n  <text x="35" y="216" font-size="11" font-weight="bold" fill="#1e3a8a">• فِي الرِّقَابِ : Özgürlüğünü kaybetmiş olanlar / borçlular</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">AYETİN SONUNDAKİ İKİ YÜCE SIFAT</text>\n  <rect x="378" y="84" width="284" height="65" rx="8" fill="#ffffff" stroke="#86efac" stroke-width="1.5"/>\n  <text x="520" y="106" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">1. اَلَّذِينَ صَدَقُوا (SÂDIKLAR)</text>\n  <text x="520" y="126" text-anchor="middle" font-size="10.5" fill="#166534">İmanında, sözünde ve davranışlarında</text>\n  <text x="520" y="141" text-anchor="middle" font-size="10.5" fill="#166534">dosdoğru ve samimi olanlar.</text>\n  <rect x="378" y="160" width="284" height="65" rx="8" fill="#ffffff" stroke="#86efac" stroke-width="1.5"/>\n  <text x="520" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">2. اَلْمُتَّقُونَ (MÜTTAKİLER)</text>\n  <text x="520" y="202" text-anchor="middle" font-size="10.5" fill="#166534">Allah\'ın emirlerine uyup yasaklarından</text>\n  <text x="520" y="217" text-anchor="middle" font-size="10.5" fill="#166534">sakınarak sorumluluk bilinci taşıyanlar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">2. ÜNİTE ÖZETİ: İSLAM\'DA İNANÇ ESASLARI (ÂMENTÜ BÜTÜNLÜĞÜ)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">ALTI İMAN ESASI (USÛL-İ SİTTE)</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#78350f">1. Allah\'a İman: Tevhid, Zâtî ve Sübûtî Sıfatlar</text>\n  <text x="35" y="118" font-size="11" font-weight="bold" fill="#78350f">2. Meleklere İman: Cebrail, Mikail, İsrafil, Azrail</text>\n  <text x="35" y="140" font-size="11" font-weight="bold" fill="#78350f">3. Kitaplara İman: Tevrat, Zebur, İncil, Kur\'an-ı Kerim</text>\n  <text x="35" y="162" font-size="11" font-weight="bold" fill="#78350f">4. Peygamberlere İman: Sıdk, Emanet, Fetanet, İsmet, Tebliğ</text>\n  <text x="35" y="184" font-size="11" font-weight="bold" fill="#78350f">5. Ahirete İman: Kıyamet, Ba\'s, Haşir, Mizan, Cennet-Cehennem</text>\n  <text x="35" y="206" font-size="11" font-weight="bold" fill="#78350f">6. Kader ve Kazaya İman: Cüz\'î irade, sorumluluk, tevekkül</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">İMANIN HAYATA YANSIMASI</text>\n  <text x="378" y="98" font-size="11" font-weight="bold" fill="#581c87">• Kalp ile Tasdik + Dil ile İkrar = İman</text>\n  <text x="378" y="124" font-size="11" font-weight="bold" fill="#581c87">• Taklidî İmandan → Tahkikî İmana Yükseliş</text>\n  <text x="378" y="150" font-size="11" font-weight="bold" fill="#581c87">• Bireysel Boyut: Anlam, ümit, iç huzur, öz denetim</text>\n  <text x="378" y="176" font-size="11" font-weight="bold" fill="#581c87">• Toplumsal Boyut: Güven (emân), adalet, merhamet</text>\n  <text x="378" y="202" font-size="11" font-weight="bold" fill="#b91c1c">• İman + Salih Amel + Güzel Ahlak = Birr (İyilik)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
